class CgmGdoiKsStatus(TextualConvention, Integer32):
    description = 'A textual convention identifying the status of Key Server in\n        the COOP/Stand-alone scenario.\n\n        Following are the possible values:\n\n          ID Type              Value\n          -------              -----\n          Alive                  1  -- Key Server is perceived as Alive\n          Dead                   2  -- Key Server is perceived as Dead\n          Unknown                3  -- Failed to determine the status;\n                                       or, the status of a secondary \n                                       peer when seen from a Secondary \n                                       Key Server.'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(1, 2, 3))
    namedValues = NamedValues(("keyServerAlive", 1), ("keyServerDead", 2), ("keyServerUnknown", 3))

